/* ====================================================================================
 *  dosinf_dotable.h -- GENERATED by tools/gen_dosinf_dotable.py. Do not edit by hand.
 *
 *  The engine's own (Frame, Count, Jump) per infantry type and action, read out of
 *  idata.cpp's <Name>Dos[DO_COUNT][3] tables. InfantryClass::Draw_It composes them as
 *
 *      shp = Frame + facenum * Jump + Fetch_Stage() %% max(Count, 1)
 *
 *  which is the ONLY bridge between a strip-local frame number, which is what this
 *  renderer computes, and an SHP frame index, which is what the Remastered art is
 *  keyed by. Jump == 0 means the action is non-directional (the deaths).
 *
 *  A row of (0, 0, 0) means the type has no art for that action.
 * ==================================================================================== */

