/* The rows for one INI name, or NULL. Linear over 20 entries; every caller does this
   once per type when a sheet is built, never per frame. */
static inline const short (*di_do_rows(const char* ini))[3]
{
    int i;
    for (i = 0; i < DI_TYPE_COUNT; i++)
        if (!strcmp(DI_DO[i].ini, ini)) return DI_DO[i].row;
    return 0;
}

